--[=[
    @class IServiceProvider
    服务提供者
]=]

export type IServiceProvider = {
    --- 释放服务提供者
    Dispose: (self: IServiceProvider) -> (),

    --- 获取必需服务
    --- @error "Service not found: {service}" -- 当服务未找到时抛出错误
    GetRequiredService: (self: IServiceProvider, service: string) -> any,

    --- 获取服务
    GetService: (self: IServiceProvider, service: string) -> any?,

    --- 创建作用域
    CreateScope: (self: IServiceProvider) -> IServiceScope
}

return {}